from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
html=ROOT/'app/src/main/assets/index.html'
s=html.read_text(encoding='utf-8')
if 'window.__starCsvImportReady' not in s:
    patch=r'''<script>(function(){if(window.__starCsvImportReady)return;window.__starCsvImportReady=true;function norm(v){return String(v??'').trim().toLowerCase().replace(/[^a-z0-9]+/g,'')}function line(v){var a=[],c='',q=false;for(var i=0;i<v.length;i++){var x=v[i];if(x==='"'){if(q&&v[i+1]==='"'){c+='"';i++;}else q=!q}else if(x===','&&!q){a.push(c);c=''}else c+=x}a.push(c);return a}function pick(o,n){for(var i=0;i<n.length;i++){var k=norm(n[i]);if(o[k]!==undefined&&String(o[k]).trim())return String(o[k]).trim()}return ''}function date(v){v=String(v||'').trim();var m=v.match(/^(\d{1,2})[\/-](\d{1,2})[\/-](\d{4})$/);return m?m[3]+'-'+String(m[2]).padStart(2,'0')+'-'+String(m[1]).padStart(2,'0'):v}window.importCustomersCsv=function(file){if(!file){toast('Select CSV first');return}var r=new FileReader();r.onload=function(){try{var ls=String(r.result||'').replace(/^\uFEFF/,'').split(/\r?\n/).filter(function(x){return x.trim()}),h=line(ls[0]).map(norm),add=0,upd=0,skip=0;for(var i=1;i<ls.length;i++){var v=line(ls[i]),o={};h.forEach(function(k,j){o[k]=v[j]??''});var name=pick(o,['name','customername','customer']),phone=pick(o,['phone','mobile','mobileno','number','whatsapp']);if(!name&&!phone){skip++;continue}var code=pick(o,['clientcode','code','customerid']);if(!code)code='SC'+String(Date.now()+i).slice(-6);var c=d.customers.find(function(x){return String(x.code||x.clientCode||'').toLowerCase()===code.toLowerCase()});if(!c){c={id:Date.now().toString()+Math.random()};d.customers.push(c);add++}else upd++;c.code=code;c.clientCode=code;c.name=name||c.name||'Customer';c.phone=phone||c.phone||'';c.address=pick(o,['address','location'])||c.address||'';c.package=pick(o,['package','pack','speed'])||c.package||'20 Mb';var fee=pick(o,['fee','monthlyfee','bill','monthlybill']);if(fee)c.fee=Number(fee.replace(/[^0-9.\-]/g,''))||0;c.pppoeUser=pick(o,['pppoeusername','pppoeuser','username'])||c.pppoeUser||'';c.pppoePass=pick(o,['pppoepassword','pppoepass','password'])||c.pppoePass||'';c.onu=pick(o,['onuid','onu'])||c.onu||'';c.connectionDate=date(pick(o,['connectiondate','createdat','joindate']))||c.connectionDate||today();c.createdAt=c.createdAt||c.connectionDate;c.expiry=date(pick(o,['expiry','expirydate','expiredate']))||c.expiry||'';var pd=pick(o,['previousdue','prevdue']);if(pd)c.prevDue=Number(pd.replace(/[^0-9.\-]/g,''))||0;var st=pick(o,['status','state']).toLowerCase();if(['active','inactive','expired'].indexOf(st)>=0)c.status=st;else if(!c.status)c.status='active'}save();try{localStorage.setItem(KEY+'_backup',JSON.stringify(d))}catch(e){}render();toast('CSV imported: '+add+' added, '+upd+' updated, '+skip+' skipped')}catch(e){toast('CSV import failed: check CSV format')}};r.readAsText(file)};window.starCsvPanel=function(){openSheet('<h3>📥 Import Customer CSV</h3><div class="muted">Your old customer list can be imported here. Same Client Code = update; new Client Code = new customer.</div><input id="starCsvFile" type="file" accept=".csv,text/csv" class="input"><button class="btn dark full" onclick="importCustomersCsv(document.getElementById(\'starCsvFile\').files[0])">📥 Import CSV</button><div class="muted" style="margin-top:8px">Columns: Client Code, Name, Phone, Address, Package, Fee, PPPoE Username, PPPoE Password, ONU ID, Connection Date, Expiry Date, Previous Due, Status.</div>')};function addCsvButton(){if(page!=='customers'||document.getElementById('starCsvBtn'))return;var c=document.getElementById('content');if(!c)return;var b=document.createElement('button');b.id='starCsvBtn';b.className='btn dark full';b.style.margin='0 0 8px';b.textContent='📥 Import Customers from CSV';b.onclick=starCsvPanel;c.insertBefore(b,c.firstChild)}var oldRender=window.render;window.render=function(){oldRender();setTimeout(addCsvButton,0)};setTimeout(addCsvButton,300)})();</script>'''
    s=s.replace('</body>',patch+'</body>')
    html.write_text(s,encoding='utf-8')

java=ROOT/'app/src/main/java/com/starcommunication/isp/MainActivity.java'
j=java.read_text(encoding='utf-8')
if 'import android.webkit.WebChromeClient;' not in j:
    j=j.replace('import android.webkit.WebViewClient;','import android.webkit.WebViewClient;\nimport android.webkit.WebChromeClient;\nimport android.webkit.ValueCallback;\nimport android.webkit.WebChromeClient.FileChooserParams;')
if 'filePathCallback' not in j:
    j=j.replace('private static final int SMS_PERMISSION_REQUEST = 7001;','private static final int SMS_PERMISSION_REQUEST = 7001;\n    private ValueCallback<Uri[]> filePathCallback;')
if 'setWebChromeClient' not in j:
    needle='webView.addJavascriptInterface(new AppBridge(),"AndroidBridge");'
    repl=needle+'''\n        webView.setWebChromeClient(new WebChromeClient(){\n            @Override public boolean onShowFileChooser(WebView view, ValueCallback<Uri[]> callback, FileChooserParams params){\n                if(filePathCallback!=null) filePathCallback.onReceiveValue(null); filePathCallback=callback;\n                try{startActivityForResult(params.createIntent(),8001);}catch(Exception e){filePathCallback=null;return false;} return true;\n            }\n        });'''
    j=j.replace(needle,repl)
if 'requestCode==8001' not in j:
    ins='''\n    @Override protected void onActivityResult(int requestCode,int resultCode,Intent data){\n        super.onActivityResult(requestCode,resultCode,data);\n        if(requestCode==8001 && filePathCallback!=null){Uri[] r=null;if(resultCode==RESULT_OK&&data!=null){if(data.getClipData()!=null){int n=data.getClipData().getItemCount();r=new Uri[n];for(int i=0;i<n;i++)r[i]=data.getClipData().getItemAt(i).getUri();}else if(data.getData()!=null)r=new Uri[]{data.getData()};}filePathCallback.onReceiveValue(r);filePathCallback=null;}\n    }\n'''
    j=j.replace('\n    @Override public void onBackPressed()',ins+'\n    @Override public void onBackPressed()')
java.write_text(j,encoding='utf-8')
print('SMS + CSV import patch applied')
